insert into public.items (kind, slug, title, tag, category_label, tune, blocks, sort_order)
values
  ('yarn', 'a-windy-night-at-camp', 'A Windy Night at Camp', 'join-in', 'Join in · sound effects', 'About 5 minutes · teach the five sounds first, then tell it slowly', '[{"type": "box", "heading": "Teach these first", "items": ["**Wind** — _Whoooosh!_ and sway like a gum tree", "**Tent** — _Zzzzip!_", "**Possum** — _Hsssss!_ with claws up", "**Billy** — _Blub, blub, blub_", "**Leader** — _Righto, you lot!_"]}, {"type": "note", "text": "Give every cue word a little extra weight and a half-second pause, so they know it is their turn."}, {"type": "verse", "text": "It was the first night of camp at Wattle Creek, and the **wind** was getting up. The **Leader** had the **billy** on the fire, and was looking up at the gum trees with a slight frown."}, {"type": "verse", "text": "\"Everyone,\" said the **Leader**, \"go and check your **tent** is pegged down properly. This **wind** is not mucking about.\""}, {"type": "verse", "text": "So off they all went. Most of them pegged their **tent** down. A few said they would do it after dinner. And one Cub, called Sam, was far too busy watching a **possum** in the tree above to do anything at all."}, {"type": "verse", "text": "After dinner the **wind** blew harder. The **billy** rattled on its hook. The **possum** came down to the lowest branch to see what was for pudding."}, {"type": "verse", "text": "At nine o''clock the **Leader** said, \"Bed.\" Everyone crawled into their **tent**, zipped it shut, and lay there listening to the **wind**."}, {"type": "verse", "text": "At ten o''clock, the **possum** found the tomato sauce."}, {"type": "verse", "text": "At eleven o''clock, the **wind** found Sam''s **tent** — the one that had not been pegged down. It lifted one corner. Then the other corner. Then the whole **tent** went cartwheeling across the campsite, with Sam still inside it, yelling."}, {"type": "verse", "text": "It rolled past the **billy**. It rolled past the **possum**, who was not happy about it. And it rolled all the way to the **Leader**''s **tent**, and stopped."}, {"type": "verse", "text": "The **Leader** unzipped the **tent**, shone a torch on the tangle of canvas and Cub, and said, very calmly: \"Pegs?\"\n\"Pegs,\" said Sam."}, {"type": "verse", "text": "So in the middle of the night, in the howling **wind**, the **Leader** and Sam pegged that **tent** down, while the **possum** sat on top of the **billy** and supervised."}, {"type": "verse", "text": "The next morning, when the **Leader** said, \"Check your **tent** is pegged down,\" every single Cub did it straight away. Even Sam. Especially Sam."}, {"type": "verse", "text": "And the **possum**? The **possum** kept the tomato sauce."}, {"type": "shout", "text": "Wind! Tent! Possum! Billy! Leader!"}, {"type": "note", "text": "Finish by rattling off all five as fast as you can. It always falls apart, and that is the fun of it."}]'::jsonb, 1),
  ('yarn', 'the-crooked-mouth-family', 'The Crooked Mouth Family', 'join-in', 'Join in · pulling faces', 'About 4 minutes · everyone pulls each face and blows with you', '[{"type": "box", "heading": "The faces", "items": ["**Dad** — mouth pulled up to one side, so he blows over his shoulder", "**Mum** — mouth pulled down to the other side, so she blows at the floor", "**Gran** — bottom lip stuck right out, so she blows up her own nose", "**Grandad** — top lip tucked over the bottom one, so he blows down his chin"]}, {"type": "note", "text": "Show each face first and get everyone to try it. They will want to do the blowing every time — let them."}, {"type": "verse", "text": "Way out past the end of the dirt road, in a little tin hut, there lived a family with a very unusual problem. Every one of them had a crooked mouth. And every mouth was crooked a different way."}, {"type": "verse", "text": "It had never bothered them much. They could eat, and talk, and sing round the fire as well as anyone. There was just one thing they could not do."}, {"type": "verse", "text": "The hut had no electricity, so every night they went to bed by the light of a single candle. And when it was time to sleep, somebody had to blow it out."}, {"type": "verse", "text": "\"I''ll do it,\" said **Dad**. He leaned over the candle, pulled his mouth up to the side, and blew — _fffffff_ — straight over his shoulder. The flame did not even wobble."}, {"type": "verse", "text": "\"Oh, move over,\" said **Mum**. She leaned over the candle, pulled her mouth down to the side, and blew — _fffffff_ — straight at the floor. The flame did not even wobble."}, {"type": "verse", "text": "\"Honestly,\" said **Gran**. She stuck her bottom lip right out and blew — _fffffff_ — straight up her own nose. Her fringe flew up. The flame did not even wobble."}, {"type": "verse", "text": "\"Let an expert have a go,\" said **Grandad**. He tucked his top lip over his bottom one and blew — _fffffff_ — straight down his chin. His beard flapped about. The flame did not even wobble."}, {"type": "verse", "text": "They tried taking turns. They tried all blowing at once. They tried standing on chairs, and lying on the floor, and blowing sideways from the doorway. The candle burned on, bright and cheerful, and not the least bit worried."}, {"type": "verse", "text": "Just then, the littlest one of the family wandered in, rubbing her eyes. She was the only one in the whole family with a perfectly straight mouth.\n\"What are you all doing?\"\n\"We can''t blow out the candle,\" they said."}, {"type": "verse", "text": "So she leaned over, and went — _ffft_."}, {"type": "verse", "text": "And the hut went dark."}, {"type": "verse", "text": "There was a long silence. Then, out of the dark, came Gran''s voice."}, {"type": "shout", "text": "\"Well. That''s what comes of all that singing round campfires.\""}, {"type": "note", "text": "If you have a real candle and the fire rules allow it, blowing it out on the littlest one''s line is a lovely finish."}]'::jsonb, 2),
  ('yarn', 'drop-bears', 'Drop Bears', 'funny', 'Funny · tall tale · keep a straight face', 'About 4 minutes · best on the first night, told like a safety briefing', '[{"type": "note", "text": "Tell it completely straight, like the fire safety talk. Make sure the youngest are let in on the joke before bed."}, {"type": "verse", "text": "_(Stand up. Serious voice.)_ Before anyone goes to bed tonight, we need to talk about drop bears."}, {"type": "verse", "text": "You all know koalas. Sleepy, fluffy, eat gum leaves, sleep twenty hours a day. Lovely animals."}, {"type": "verse", "text": "Drop bears are their cousins. They are about the size of a big dog. They have the same fluffy ears. They live high up in exactly this kind of gum tree. _(Look up. Slowly.)_ And they do not eat gum leaves."}, {"type": "verse", "text": "A drop bear waits on a branch, very still, until something walks underneath. Then it lets go, and drops. Straight down. Onto your head."}, {"type": "verse", "text": "So there are three rules, and everyone needs to listen."}, {"type": "box", "heading": "The rules", "items": ["**Never stand under a gum tree after dark.** If you have to walk under one, walk quickly and do not look up. Looking up is how they know you have noticed them.", "**Vegemite behind the ears.** Drop bears cannot stand the smell. If you did not bring any, see a leader — we keep a jar for emergencies.", "**Talk like an Aussie.** Drop bears never go for locals; they can tell by the accent. If you are visiting from overseas, or from Adelaide, practise your \"G''day\" before bed."]}, {"type": "verse", "text": "Now, some people think this is a joke. A couple of years back, a leader came to this very camp all the way from England. He laughed at the Vegemite. He laughed at the rules. He put his tent up right under the biggest gum tree on the site, and he said, \"Drop bears? Pull the other one.\""}, {"type": "verse", "text": "That night, the whole camp heard a thump."}, {"type": "verse", "text": "In the morning, his tent was flat as a pancake. There were big muddy pawprints all over it. And his Vegemite sandwich was gone."}, {"type": "verse", "text": "He was fine. He went home a day early, that''s all. And they say that to this day he never goes outside without a fork stuck in his hat. Just in case."}, {"type": "verse", "text": "So. Vegemite behind the ears. Stay out from under the gum trees. And whatever you do, when you walk back to your tent tonight —"}, {"type": "shout", "text": "DON''T. LOOK. UP."}, {"type": "note", "text": "If another leader, out of sight, gives a branch a good shake on that last line, so much the better."}]'::jsonb, 3),
  ('yarn', 'the-chip-monk', 'The Chip Monk', 'funny', 'Funny · shaggy dog · groan ending', 'About 6 minutes · the longer you stretch it, the bigger the groan', '[{"type": "note", "text": "A shaggy dog story lives on its details. Take your time with the rain, the blisters and the smell of the chips — every extra minute makes the groan at the end louder."}, {"type": "verse", "text": "This happened to a Rover I know. I won''t tell you his name, because he still hasn''t lived it down."}, {"type": "verse", "text": "One Saturday he set out to walk the long track over the ranges — thirty kilometres, up one side and down the other. He packed a map, a raincoat, two litres of water and exactly one muesli bar, because he was definitely going to be home in time for dinner."}, {"type": "verse", "text": "By ten o''clock, he had eaten the muesli bar.\nBy twelve o''clock, it was raining.\nBy two o''clock, he had taken a wrong turn at a fallen tree, and the track was getting narrower, and steeper, and muddier, and did not seem to be on the map at all."}, {"type": "verse", "text": "He walked for another two hours. His boots squelched. His socks squelched. His stomach growled so loudly that a lyrebird in the scrub started copying it."}, {"type": "verse", "text": "And then, just as the light was going, he came over a rise and stopped dead. Because on the wind there was a smell. Hot oil. Salt. Vinegar."}, {"type": "verse", "text": "Chips."}, {"type": "verse", "text": "Down in the valley was an old stone building with a little bell tower, and a hand-painted sign on the gate: **Monastery. Visitors welcome. Fish and chips on Saturdays.**"}, {"type": "verse", "text": "He ran. Squelch, squelch, squelch, all the way down the hill."}, {"type": "verse", "text": "Inside, it was warm and very quiet. Behind a wooden counter stood a monk in a long brown robe, and behind him was a kitchen with two great bubbling fryers. The monk smiled, and pointed to a small card: **We have taken a vow of silence. Please point.**"}, {"type": "verse", "text": "So the Rover pointed. He pointed at the word \"fish\", and held up two fingers. He pointed at the word \"chips\", and held his arms out as wide as they would go. The monk nodded gravely, and went into the kitchen."}, {"type": "verse", "text": "And from the kitchen came the most beautiful sounds he had ever heard. Sizzle. Crackle. A good hard shake of salt."}, {"type": "verse", "text": "He sat by the fire and steamed gently, and ten minutes later the monk came back with the biggest plate of fish and chips he had ever seen. He ate the lot. He ate the crumbs. He very nearly ate the plate."}, {"type": "verse", "text": "When he had finished, he went back to the counter to say thank you — and found there were now two monks behind it. The one who had served him, and another with flour on his sleeves and salt in his eyebrows."}, {"type": "verse", "text": "\"It''s all right, we''re allowed to talk after dinner,\" said the first monk. \"Did you enjoy it?\"\n\"That was the best meal of my whole life,\" said the Rover. \"I have to know. Who cooked that fish?\"\n\"That was me,\" said the first monk. \"I''m the fish friar.\""}, {"type": "verse", "text": "The Rover turned to the other monk. \"Then you must be the one who did the chips.\""}, {"type": "shout", "text": "\"That''s right. I''m the chip monk.\""}, {"type": "note", "text": "Say the last line and stop. Do not explain it. Let them get there on their own."}]'::jsonb, 4),
  ('yarn', 'in-a-dark-dark-wood', 'In a Dark, Dark Wood', 'spooky', 'Spooky · for the little ones', 'About 2 minutes · Joeys and Cubs · everyone says "dark, dark" with you', '[{"type": "note", "text": "Say it slower and quieter with every line, and lean in closer. Hold the pause before the last word for as long as you dare."}, {"type": "verse", "text": "In a **dark, dark** wood, there was a **dark, dark** path.\nAnd down that **dark, dark** path, there was a **dark, dark** house."}, {"type": "verse", "text": "And in that **dark, dark** house, there was a **dark, dark** hall.\nAnd down that **dark, dark** hall, there was a **dark, dark** door."}, {"type": "verse", "text": "And behind that **dark, dark** door, there was a **dark, dark** room.\nAnd in that **dark, dark** room, there was a **dark, dark** cupboard."}, {"type": "verse", "text": "And in that **dark, dark** cupboard, there was a **dark, dark** box.\nAnd in that **dark, dark** box, there was . . ."}, {"type": "shout", "text": "A GHOST!"}, {"type": "note", "text": "For a bush version, make it a dark, dark gully, a dark, dark hut, a dark, dark swag and a dark, dark boot — and finish on \"A HUNTSMAN!\""}]'::jsonb, 5),
  ('yarn', 'the-hairy-toe', 'The Hairy Toe', 'spooky', 'Spooky · jump at the end', 'About 4 minutes · Cubs and up · slower and quieter right up to the last word', '[{"type": "note", "text": "Everyone can whisper the voice''s lines with you. On the very last line, point straight at someone in the front row. Check the youngest are sitting next to a leader first."}, {"type": "verse", "text": "Once, a long way from town, there lived an old woman on her own. She had a little house, a vegie patch, a dog called Biscuit, and not much else."}, {"type": "verse", "text": "One evening she was out digging potatoes for her tea, when her fork hit something that was not a potato. She scraped the dirt away, and there, sticking up out of the ground, was a toe."}, {"type": "verse", "text": "A big toe. A big, hairy toe."}, {"type": "verse", "text": "\"Well, that''s peculiar,\" said the old woman. And because she never wasted anything, she wiped it on her apron, popped it in the apron pocket, and hung the apron on the end of her bed."}, {"type": "verse", "text": "That night, as she lay in bed, the wind got up. It moaned round the chimney and rattled the windows. And far, far away, down past the end of the road, she heard a voice on the wind."}, {"type": "verse", "text": "**Where''s my hair-r-ry to-o-oe?**\n**Who''s got my hair-r-ry to-o-oe?**"}, {"type": "verse", "text": "The old woman pulled the blanket up to her chin. Biscuit whimpered under the bed."}, {"type": "verse", "text": "The voice came closer. It was at the front gate now.\n**Where''s my hair-r-ry to-o-oe?**\n**Who''s got my hair-r-ry to-o-oe?**"}, {"type": "verse", "text": "The old woman pulled the blanket up to her nose."}, {"type": "verse", "text": "The voice came closer. The front door creaked open. It was in the kitchen now, and she could hear it opening the cupboards, one by one.\n**Where''s my hair-r-ry to-o-oe?**\n**Who''s got my hair-r-ry to-o-oe?**"}, {"type": "verse", "text": "The old woman pulled the blanket right up over her head."}, {"type": "verse", "text": "The bedroom door creaked. Slow footsteps crossed the floor. Something stood at the end of the bed, right beside the apron. And a voice whispered . . .\n**Where''s my hair-r-ry to-o-oe?**\n**Who''s . . . got . . . my . . . hair-r-ry . . . to-o-oe?**"}, {"type": "shout", "text": "_(Point at someone.)_ YOU''VE GOT IT!"}]'::jsonb, 6),
  ('yarn', 'the-wind-and-the-sun', 'The Wind and the Sun', 'quiet', 'Quiet · a fable', 'About 3 minutes · a calm one for when the fire is low', '[{"type": "verse", "text": "One afternoon, high above a long dusty road, the Wind and the Sun got into an argument about which of them was the stronger."}, {"type": "verse", "text": "\"It''s obviously me,\" said the Wind. \"I can bend the gum trees flat. I can whip the sea into waves as tall as houses. I can blow the roof off a shed.\"\n\"Maybe so,\" said the Sun. \"But being strong isn''t only about shoving things around.\""}, {"type": "verse", "text": "Just then, they saw a drover riding along the road below, wrapped up in a long oilskin coat."}, {"type": "verse", "text": "\"Here''s a test, then,\" said the Sun. \"Whichever of us can get that coat off him is the stronger.\"\n\"Easy,\" said the Wind. \"Watch this.\""}, {"type": "verse", "text": "The Wind took a deep breath and blew. Dust flew up off the road. The grass lay down flat. The drover''s hat went spinning away over the paddocks."}, {"type": "verse", "text": "But the harder the Wind blew, the tighter the drover pulled his coat around him. He did up every button. He turned up the collar. He hunched down in the saddle and held the coat shut with both hands."}, {"type": "verse", "text": "The Wind blew until it had no breath left at all, and the coat stayed exactly where it was."}, {"type": "verse", "text": "\"My turn,\" said the Sun."}, {"type": "verse", "text": "The Sun didn''t shout, and it didn''t push. It just came out from behind a cloud and shone, quietly and warmly, on the road."}, {"type": "verse", "text": "After a while, the drover undid his top button. A little later, he undid the rest. And before long he pulled up under a tree, took the long oilskin coat off altogether, and laid it across the saddle with a sigh."}, {"type": "verse", "text": "The Wind said nothing for a long time."}, {"type": "note", "text": "If it suits the night, leave it there. Or add, gently: some things you will never get from people by pushing — but you can get almost anything by being warm."}]'::jsonb, 7),
  ('yarn', 'stone-soup', 'Stone Soup', 'quiet', 'Quiet · for the end of the night', 'About 5 minutes · a gentle one to finish on', '[{"type": "verse", "text": "Long ago, in a hard winter, a traveller came walking into a small village with nothing but a cooking pot on her back."}, {"type": "verse", "text": "She was tired and hungry, and she knocked on doors asking if anyone could spare a little food. But times were hard, and the villagers were worried about their own families. \"Sorry,\" they said, one after another. \"We''ve nothing to spare.\" And they closed their doors."}, {"type": "verse", "text": "So the traveller walked to the middle of the village square, filled her pot with water from the well, and lit a small fire underneath it. Then she took a smooth grey stone out of her pocket, looked at it fondly, and dropped it into the pot. _Plop._"}, {"type": "verse", "text": "A boy was watching from a doorway. \"What are you making?\"\n\"Stone soup,\" said the traveller. \"It''s delicious. Although,\" she added, stirring, \"it''s even better with an onion.\"\nThe boy thought about the onion in his mother''s kitchen. He ran to get it."}, {"type": "verse", "text": "An old man came over to see what the fuss was about. The traveller tasted the soup. \"Mmm. Coming along nicely. A carrot or two would really bring it out, though.\"\nThe old man had a few carrots. He fetched them."}, {"type": "verse", "text": "One by one, people came out to look. And one by one, they remembered something. A handful of potatoes. A pinch of salt. A cabbage. Some barley. A bit of leftover meat. Somebody brought bread. Somebody brought bowls. Somebody brought a fiddle."}, {"type": "verse", "text": "And as the sun went down, the whole village sat together round the fire in the square, eating the best soup any of them could remember, and singing."}, {"type": "verse", "text": "Late in the night, when everyone had gone home, the traveller fished the stone out of the pot, wiped it dry, and put it back in her pocket for the next village."}, {"type": "note", "text": "A good one to finish on, because a campfire works the same way. Nobody brings much. Everybody brings something."}]'::jsonb, 8)
